  ["AUTO-CALIBRATING: stretch arms STRAIGHT OUT to the sides,"] = "AUTOCALIBRANDO: extiende los brazos RECTOS HACIA LOS LADOS,",
  ["stand straight facing forward. Hold for %.1fs (%.0f%%)."] = "ponte erguido mirando al frente. Mantén %.1f s (%.0f%%).",
  ["Start Auto-Calibration (T-pose, 4s)"] = "Iniciar autocalibración (pose en T, 4 s)",
  ["Press once, then stretch BOTH gizmo hands OUT to the sides at shoulder height\nand stand straight facing forward. The mod measures the visible controller\npositions, computes shoulder pivots + arm scale, and saves the result\nto vrik_calibration.ini."] = "Presiona una vez y extiende AMBAS manos gizmo HACIA LOS LADOS a la altura de los hombros\ny ponte erguido mirando al frente. El mod mide las posiciones visibles\nde los controles, calcula los pivotes de hombro + la escala de brazos y guarda el resultado\nen vrik_calibration.ini.",
  ["Saved."] = "Guardado.",
  ["Camera: neck + 15 cm forward, eyes + 10 cm up"] = "Cámara: cuello + 15 cm adelante, ojos + 10 cm arriba",
  ["Reset camera to neck"] = "Restablecer cámara al cuello",
  ["Uses the neutral neck, 15 cm forward and 10 cm above reference eyes.\nResets camera trims; no stance, head direction or Bake measurement is needed."] = "Usa el cuello neutro, 15 cm adelante y 10 cm por encima de los ojos de referencia.\nRestablece los ajustes de cámara; no hace falta postura, dirección de la cabeza ni medición Bake.",
  ["Clear trim"] = "Borrar ajuste",
  ["camera mount: R %.3f  Fwd %.3f  Up %.3f"] = "montaje de cámara: R %.3f  Adelante %.3f  Arriba %.3f",
