  ["Stereo module not installed."] = "Módulo estéreo no instalado.",
  ["The engine hooks did not load, so everything below is inert and the headset is on the plain mono path. Either CyberpunkVR_StereoModuleEnable is 0, or bin\\x64\\vrport_nostereo.txt exists. See the \"Stereo:\" line in cyberpunkvrport.log."] = "Los hooks del motor no se cargaron, así que todo lo de abajo está inactivo y el visor va por la ruta mono simple. O CyberpunkVR_StereoModuleEnable vale 0, o existe bin\\x64\\vrport_nostereo.txt. Consulta la línea \"Stereo:\" en cyberpunkvrport.log.",
  ["LEFT"] = "IZQUIERDO",
  ["RIGHT"] = "DERECHO",
  ["Stereo active  (%s = VRCAM, %s = MAIN)"] = "Estéreo activo  (%s = VRCAM, %s = MAIN)",
  ["No second eye right now -> both eyes get MAIN (mono)"] = "Ahora no hay segundo ojo -> ambos ojos reciben MAIN (mono)",
  ["Expected in menus and while loading. If it stays here in gameplay: the VRCAM component is off, or vrcam.json names a camera the player entity does not carry."] = "Normal en menús y durante las cargas. Si sigue así en juego: el componente VRCAM está desactivado o vrcam.json nombra una cámara que la entidad del jugador no tiene.",
  ["Stereo submit off -> both eyes get MAIN (mono)"] = "Envío estéreo desactivado -> ambos ojos reciben MAIN (mono)",
  ["vrcam eye age %u ms  (stale over %u)   eye submits %llu"] = "edad del ojo vrcam %u ms  (obsoleto tras %u)   envíos del ojo %llu",
  ["vrcam eye: never produced a frame"] = "ojo vrcam: nunca ha producido un cuadro",
  ["Send VRCAM to the %s EYE"] = "Enviar VRCAM al OJO %s",
  ["Off = the old behaviour, MAIN duplicated into both eyes.\nOn = the %s eye gets the VRCAM view's own final colour --\nthe same image the desktop mirror shows -- re-encoded to the\nswapchain's sRGB format and scaled to the eye size."] = "Desactivado = comportamiento anterior, MAIN duplicado en ambos ojos.\nActivado = el ojo %s recibe el color final propio de la vista VRCAM --\nla misma imagen que muestra el espejo del escritorio -- recodificada al\nformato sRGB de la swapchain y escalada al tamaño del ojo.",
  ["snapshot copies %llu   skips %llu   vrcam RTV hits %llu"] = "copias de instantánea %llu   omisiones %llu   aciertos RTV vrcam %llu",
  ["Eye staleness limit (ms)"] = "Límite de antigüedad del ojo (ms)",
  ["How long the last VRCAM frame stays usable. Past this the %s\neye falls back to MAIN -- one eye frozen while the other moves\nis far worse to look at than mono."] = "Cuánto tiempo sigue siendo útil el último cuadro VRCAM. Después, el ojo %s\nvuelve a MAIN -- un ojo congelado mientras el otro se mueve\nes mucho peor de ver que el mono.",
  ["VRCAM DLSS: %s  (follows MAIN's upscaler, no switch)"] = "VRCAM DLSS: %s  (sigue al escalador de MAIN, sin interruptor)",
  ["ON"] = "ENCENDIDA",
  ["off"] = "desactivado",
  ["On whenever MAIN is upscaling with DLSS: vrcam gets its own\nStreamline viewport and renders below its target.\nOff for DLAA / TAA / no upscaler. Change it in the game's\ngraphics settings, not here."] = "Activo siempre que MAIN escale con DLSS: vrcam obtiene su propio\nviewport de Streamline y renderiza por debajo de su objetivo.\nInactivo con DLAA / TAA / sin escalador. Se cambia en los ajustes\ngráficos del juego, no aquí.",
  ["Match VRCAM projection to MAIN  (fov / zoom / near / far)"] = "Igualar la proyección de VRCAM a MAIN  (fov / zoom / near / far)",
  ["VRCAM component  (RTTI Toggle: force ON/OFF)"] = "Componente VRCAM  (conmutador RTTI: forzar ON/OFF)",
  ["component %s   camera %s"] = "componente %s   cámara %s",
  ["view nodes: main %llu   other %llu   vrcam %llu"] = "nodos de vista: main %llu   otros %llu   vrcam %llu",
  ["VRCAM Mirror  (separate window, for capture)"] = "Espejo VRCAM  (ventana aparte, para capturar)",
  ["vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f"] = "vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f",
  ["Diagnostics"] = "Diagnóstico",
  ["Compact ADS camera telemetry (in-headset)"] = "Telemetría compacta de la cámara ADS (en el visor)",
  ["A small panel that stays up after F10 is closed, reporting what the ENGINE did to the camera when the sights came up:\ndelta and peak in centimetres, right/forward/up in the heading's own basis, against a baseline captured while hip firing.\nStereo submission is unaffected."] = "Un pequeño panel que permanece tras cerrar F10 e informa de lo que el MOTOR hizo a la cámara al subir la mira:\ndelta y pico en centímetros, derecha/adelante/arriba en la base propia de la orientación, frente a una referencia tomada disparando desde la cadera.\nEl envío estéreo no se ve afectado.",
  ["Telemetry X"] = "Telemetría X",
  ["Telemetry Y"] = "Telemetría Y",
  ["Normalised position in the eye image"] = "Posición normalizada en la imagen del ojo",
  ["Stereo logging -> cyberpunkvrport.log"] = "Registro estéreo -> cyberpunkvrport.log",
  ["Committed snapshot of the VRCAM final"] = "Instantánea fijada de la imagen final de VRCAM",
  ["Off = read the engine's transient directly. That target is a\nframe-graph allocation which a later pass aliases, which is what\nmade the image alternate bright/dark. Leave on."] = "Desactivado = leer directamente el objetivo temporal del motor. Ese objetivo es una\nasignación del frame graph que un pase posterior reutiliza, lo que\nhacía alternar la imagen entre clara y oscura. Déjalo activado.",
  ["Snapshot at the tonemap node instead of RenderFinal2D"] = "Instantánea en el nodo de tonemap en lugar de RenderFinal2D",
  ["Node CPU profiler  (per-node self+incl ms)"] = "Perfilador de CPU de nodos  (ms propios+incl. por nodo)",
  ["frame %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)"] = "cuadro %.2f ms   despacho: main %.2f (%u)  vrcam %.2f (%u)",
  ["Dump node audit -> log  (resets window)"] = "Auditoría de nodos -> registro  (reinicia la ventana)",
  ["top %d by self ms/frame   (main | vrcam)"] = "top %d por ms propios/cuadro   (main | vrcam)",
  ["Driving -- hands on the wheel"] = "Conducción -- manos en el volante",
  ["Grab the wheel with the grips"] = "Agarrar el volante con los gatillos laterales",
  ["While DRIVING, bring a hand to where the driving animation holds the\nwheel (or the handlebars) and squeeze that grip: the arm is handed back\nto the game's own animation -- hand on the wheel, fingers wrapped around\nit -- instead of following the controller. Release the grip and it goes\nback to your hand.\n\nEach hand is independent: hold the wheel with one and keep the other on\na gun. While a hand is at the wheel that grip does nothing else (no\nholster equip, no magazine grab)."] = "Al CONDUCIR, lleva una mano adonde la animación de conducción sujeta el\nvolante (o el manillar) y aprieta ese gatillo lateral: el brazo vuelve\na la animación del juego -- mano en el volante, dedos alrededor\nde él -- en lugar de seguir al control. Suelta el gatillo y vuelve\na tu mano.\n\nCada mano es independiente: sujeta el volante con una y mantén la otra en\nun arma. Mientras una mano está en el volante, ese gatillo no hace nada más (no\nequipa desde la funda ni agarra cargadores).",
  ["Grab radius (m)"] = "Radio de agarre (m)",
  ["How close your hand has to be to the animated hand before the\ngrip counts as grabbing the wheel. Bigger = easier to catch a\nwheel you cannot see; too big and every grip in a car grabs."] = "Lo cerca que debe estar tu mano de la mano animada para que el\ngatillo cuente como agarrar el volante. Mayor = más fácil atrapar un\nvolante que no ves; demasiado y cualquier agarre en el auto toma el volante.",
  ["Car full lock at (deg)"] = "Giro completo a (°)",
  ["Wheel sensitivity: hand rotation from the grab position to full lock.\nOne hand uses a hub calibrated where you grab; two use their connecting line.\nAdding or releasing a hand keeps the current turn.\n180 = a half turn to either full lock (default). Lower = more sensitive.\nThe car's cabin wheel has twice its native travel; road-wheel lock is unchanged.\nTravel beyond full lock keeps the same neutral position."] = "Sensibilidad del volante: giro de la mano desde la posición de agarre hasta el tope.\nUna mano usa un cubo calibrado donde agarras; dos usan la línea que las une.\nAñadir o soltar una mano conserva el giro actual.\n180 = media vuelta hasta cada tope (predeterminado). Menos = más sensible.\nEl volante de la cabina tiene el doble de recorrido nativo; el giro de las ruedas no cambia.\nEl recorrido más allá del tope mantiene la misma posición neutra.",
  ["Steering deadzone (deg)"] = "Zona muerta de dirección (°)",
  ["Tilt around centre that steers nothing at all.\nRaise it if the car drifts while you hold the wheel straight;\nevery degree here is a degree of dead wheel off centre.\nThe full range still ends at 'Full lock at', so widening the\ndeadzone does not make the steering jump."] = "Inclinación alrededor del centro que no gira nada.\nSúbela si el auto se desvía mientras sujetas el volante recto;\ncada grado aquí es un grado de volante muerto fuera del centro.\nEl rango completo sigue terminando en «Giro completo a», así que ampliar la\nzona muerta no hace que la dirección dé saltos.",
  ["Steering prediction"] = "Predicción de dirección",
  ["Gently anticipate a continuing turn from recent hand movement.\nLimited to 8 ms and 0.5 degrees; neutral stays unchanged.\nPrediction stops on a pause, reversal or grip change.\nOff by default. It cannot anticipate the start of a turn."] = "Anticipa suavemente un giro continuado a partir del movimiento reciente de la mano.\nLimitada a 8 ms y 0.5°; el punto neutro no cambia.\nLa predicción se detiene ante una pausa, un cambio de sentido o de agarre.\nDesactivada por defecto. No puede anticipar el inicio de un giro.",
  ["Prediction horizon (ms)"] = "Horizonte de predicción (ms)",
  ["Horn -- hand on the wheel hub"] = "Claxon -- mano en el centro del volante",
  ["While DRIVING, put a hand on the MIDDLE of the wheel -- where you would\nslap a real horn -- and the car honks for as long as it stays there.\nNo grip needed; a hand that is GRABBING the wheel never honks."] = "Al CONDUCIR, pon una mano en el CENTRO del volante -- donde\ngolpearías un claxon real -- y el auto pita mientras siga ahí.\nNo hace falta gatillo; una mano que AGARRA el volante nunca pita.",
  ["Horn hub radius (m)"] = "Radio del centro del claxon (m)",
  ["How near the wheel centre the hand counts as on the hub.\nBigger = easier to find the horn without seeing it; too big\nand it reaches the rim, so every grab honks."] = "Lo cerca del centro del volante que la mano cuenta como en el cubo.\nMayor = claxon más fácil de encontrar sin verlo; demasiado\ny llega al aro, así que cada agarre pita.",
  ["Trigger fires the gun while driving"] = "El gatillo dispara el arma al conducir",
  ["Draw a weapon in the driver seat and the RIGHT TRIGGER stops being the\nthrottle and becomes the gun: drive with the left hand on the wheel and\nshoot with the right.\n\nThe throttle LATCHES at whatever it was when the weapon came out, so the\ncar keeps rolling, and the LEFT STICK forward/back trims that speed while\nyou shoot. Holster the weapon and the trigger is the throttle again.\n\nWhile the weapon is out the left stick's forward/back is taken by the\ntrim: no lean / rock and no autodrive gesture until you holster."] = "Saca un arma en el asiento del conductor y el GATILLO DERECHO deja de ser el\nacelerador y pasa a ser el arma: conduce con la mano izquierda en el volante y\ndispara con la derecha.\n\nEl acelerador se QUEDA FIJO en el valor que tenía al sacar el arma, así que el\nauto sigue rodando, y el STICK IZQUIERDO adelante/atrás ajusta esa velocidad mientras\ndisparas. Guarda el arma y el gatillo vuelve a ser el acelerador.\n\nMientras el arma está fuera, el adelante/atrás del stick izquierdo lo usa el\najuste: sin inclinarse / balancearse ni gesto de conducción automática hasta que guardes el arma.",
  ["Throttle trim rate (/s)"] = "Ritmo de ajuste del acelerador (/s)",
  ["How much of the throttle's full travel the left stick adds or\nremoves per second while a weapon is out.\n0.5 = two seconds held to go from idle to floored."] = "Qué parte del recorrido total del acelerador añade o\nquita el stick izquierdo por segundo con un arma fuera.\n0.5 = dos segundos sostenidos para pasar de ralentí a fondo.",
  ["driving %d   at wheel  L %d R %d   hold  L %.2f R %.2f"] = "conducción %d   en volante  L %d R %d   agarre  L %.2f R %.2f",
  ["steer  %+.1f deg  ->  stick %+.2f     horn  L %d R %d"] = "dirección  %+.1f°  ->  stick %+.2f     claxon  L %d R %d",
  ["SEATED CAMERA OFFSET"] = "DESPLAZAMIENTO DE CÁMARA SENTADO",
  ["Head offsets in GENERAL are a standing calibration. Seated, the game's own\nvehicle camera is already where it should be -- which is why the port drops\nits two automatic bakes in a vehicle -- so a standing offset carries the view\noff the seat instead of correcting it.\n\nThese three are added to the Head sliders while you are in a vehicle and\nignored the moment you step out, so the car and the street can be tuned\nseparately. Zero = the car keeps exactly the offset it has today."] = "Los desplazamientos de cabeza de GENERAL son una calibración de pie. Sentado, la cámara\ndel vehículo del juego ya está donde debe -- por eso el port descarta\nsus dos ajustes automáticos en un vehículo -- así que un desplazamiento de pie saca la vista\ndel asiento en lugar de corregirla.\n\nEstos tres se suman a los deslizadores de cabeza mientras estás en un vehículo y\nse ignoran en cuanto te bajas, para ajustar el auto y la calle\npor separado. Cero = el auto mantiene exactamente su desplazamiento actual.",
  ["Car Head X right"] = "Cabeza en auto X derecha",
  ["Car Head Y forward"] = "Cabeza en auto Y adelante",
  ["Car Head Z up"] = "Cabeza en auto Z arriba",
  ["   (window combat: use GENERAL > Head offsets)"] = "   (combate desde ventanilla: usa GENERAL > desplazamientos de cabeza)",
