  ["GENERAL"] = "GENERAL",
  ["CAS Sharpening"] = "Nitidez CAS",
  ["Contrast-adaptive sharpening for both eyes. 0 = off, 1 = full strength. Disabled automatically with game DLAA."] = "Nitidez adaptativa al contraste para ambos ojos. 0 = desactivada, 1 = máxima. Se desactiva automáticamente con el DLAA del juego.",
  ["FIXED FOVEATED RENDERING"] = "RENDERIZADO FOVEADO FIJO",
