  ["Quality"] = "Calidad",
  ["Balanced"] = "Equilibrado",
  ["Performance"] = "Rendimiento",
  ["The center follows game DLSS/DLAA. Peripheral DLAA uses 100%% / 75%% / 50%% of the game's render resolution."] = "El centro sigue al DLSS/DLAA del juego. El DLAA periférico usa el 100%% / 75%% / 50%% de la resolución de renderizado del juego.",
  ["Center width"] = "Ancho del centro",
  ["Full-quality region width as a percentage of each eye image."] = "Ancho de la zona de calidad completa como porcentaje de la imagen de cada ojo.",
  ["Center height"] = "Alto del centro",
  ["Full-quality region height as a percentage of each eye image."] = "Alto de la zona de calidad completa como porcentaje de la imagen de cada ojo.",
  ["Center offset X"] = "Desplazamiento del centro X",
  ["Percentage of eye-image width. Negative = left, positive = right."] = "Porcentaje del ancho de la imagen del ojo. Negativo = izquierda, positivo = derecha.",
  ["Center offset Y"] = "Desplazamiento del centro Y",
  ["Percentage of eye-image height. Negative = up, positive = down toward the hands."] = "Porcentaje del alto de la imagen del ojo. Negativo = arriba, positivo = abajo hacia las manos.",
  ["Show region boundary"] = "Mostrar límite de la zona",
  ["DLSS GPU: native %.2f ms / foveated %.2f ms"] = "DLSS GPU: nativo %.2f ms / foveado %.2f ms",
  ["Shared sun shadows"] = "Sombras solares compartidas",
  ["Render sun cascades once for both eyes. Shadow quality and distance remain controlled by the game."] = "Renderiza las cascadas solares una vez para ambos ojos. La calidad y la distancia de las sombras las sigue controlando el juego.",
  ["Scope lens stabilization"] = "Estabilización de la lente de la mira",
  ["Magnifying scope lenses while the view moves: share of the stabilised image (percent). Higher: no blinking of lights and grates, softer. 0 = off. Standing still the lens is untouched."] = "Lentes de aumento de las miras mientras la vista se mueve: proporción de la imagen estabilizada (porcentaje). Más alto: sin parpadeo de luces y rejillas, más suave. 0 = desactivado. Quieto, la lente no cambia.",
  ["VARIABLE RATE SHADING"] = "SOMBREADO DE TASA VARIABLE",
  ["Peripheral shading"] = "Sombreado periférico",
  [" 2 x 2"] = " 2 x 2",
  [" 4 x 4"] = " 4 x 4",
  ["Opaque scene materials in both eyes. The center stays 1 x 1. Unsupported 4 x 4 falls back to 2 x 2."] = "Materiales opacos de la escena en ambos ojos. El centro se queda en 1 x 1. Sin soporte, 4 x 4 pasa a 2 x 2.",
  ["Unavailable: GPU resource error"] = "No disponible: error de recursos de GPU",
  ["VRS Tier 2 unavailable"] = "VRS Tier 2 no disponible",
  ["Preparing"] = "Preparando",
  ["%s | %u px tiles"] = "%s | mosaicos de %u px",
  ["4 x 4"] = "4 x 4",
  ["2 x 2"] = "2 x 2",
  ["HIDDEN AREA MASK"] = "MÁSCARA DE ZONA OCULTA",
  ["Mask lens edges"] = "Enmascarar bordes de las lentes",
  ["Skips shading the parts of each eye image the lens never shows. The visible area is unchanged."] = "Omite el sombreado de las partes de la imagen de cada ojo que la lente nunca muestra. La zona visible no cambia.",
  ["Visible radius"] = "Radio visible",
  ["Size of the shaded area as a percentage of the eye's field of view: 100%% touches its edges, 141%% masks nothing inside it.\nLower it until a dark border appears at the edge of the lens, then raise it until the border is gone."] = "Tamaño de la zona sombreada como porcentaje del campo de visión del ojo: 100%% toca sus bordes, 141%% no enmascara nada dentro.\nBájalo hasta que aparezca un borde oscuro en el filo de la lente y luego súbelo hasta que desaparezca.",
  ["Waiting for the scene depth"] = "Esperando la profundidad de la escena",
  ["Masked %.1f %% / %.1f %% of pixels (MAIN / VRCAM)"] = "Enmascarado %.1f %% / %.1f %% de los píxeles (MAIN / VRCAM)",
  ["GAME MENUS"] = "MENÚS DEL JUEGO",
  ["VR menu quad"] = "Plano del menú VR",
  ["VR menu FOV"] = "FOV del menú VR",
  ["Tracking / Camera"] = "Seguimiento / cámara",
  ["Locomotion direction is set in the Controls tab."] = "La dirección de desplazamiento se ajusta en la pestaña Controles.",
  ["Disable Mouse Y (Pitch)"] = "Desactivar mouse Y (cabeceo)",
  ["Suppress mouse/right-stick pitch so only the HMD controls\nvertical look. Applied by the CET VRIK mod and the\nXInput merge. On by default."] = "Suprime el cabeceo del mouse/stick derecho para que solo el HMD controle\nla vista vertical. Lo aplican el mod CET VRIK y la\nfusión XInput. Activado por defecto.",
  ["Head X right"] = "Cabeza X derecha",
  ["Head Y forward"] = "Cabeza Y adelante",
  ["Head Z up"] = "Cabeza Z arriba",
  ["Debug Gizmos"] = "Gizmos de depuración",
  ["Raw hand overlay / debug gizmos:"] = "Superposición de manos en bruto / gizmos de depuración:",
  ["Enable hand overlay"] = "Activar superposición de manos",
  ["Draw 3D hand proxy"] = "Dibujar mano 3D",
  ["Draw debug wire/axes"] = "Dibujar líneas/ejes de depuración",
  ["Locator scale"] = "Escala de los localizadores",
  ["Verbose log (spammy diag)"] = "Registro detallado (mucho diagnóstico)",
  ["Off by default for a clean cyberpunkvrport.log. Enable only\nwhen capturing ClipCursor / depth / hook diagnostics."] = "Desactivado por defecto para un cyberpunkvrport.log limpio. Actívalo solo\nal capturar diagnósticos de ClipCursor / profundidad / hooks.",
  ["FRAMEGEN"] = "GEN. FOTOG.",
  ["Enable frame generation"] = "Activar generación de cuadros",
  ["While frame generation is enabled, hand smoothing runs at its rate times xr_hand_lerp_framegen_scale (1.5; 0 turns it off)."] = "Con la generación de cuadros activa, el suavizado de manos va a su frecuencia multiplicada por xr_hand_lerp_framegen_scale (1.5; 0 lo desactiva).",
  ["Frame generator"] = "Generador de cuadros",
  ["FidelityFX"] = "FidelityFX",
  ["NVIDIA OFA + FidelityFX"] = "NVIDIA OFA + FidelityFX",
  ["NVIDIA DLSS Frame Generation"] = "NVIDIA DLSS Frame Generation",
  ["DLSS Frame Generation is not available here (%s); FidelityFX is used."] = "DLSS Frame Generation no está disponible aquí (%s); se usa FidelityFX.",
  ["NVIDIA optical flow is not available on this GPU; FidelityFX optical flow is used."] = "El flujo óptico de NVIDIA no está disponible en esta GPU; se usa el flujo óptico de FidelityFX.",
  ["NVIDIA quality"] = "Calidad NVIDIA",
  ["Fast (performance)"] = "Rápido (rendimiento)",
  ["Medium (balanced)"] = "Medio (equilibrado)",
  ["Slow (best)"] = "Lento (mejor)",
  ["Optical flow"] = "Flujo óptico",
  ["Off (game vectors only)"] = "Desactivado (solo vectores del juego)",
  ["The game's motion vectors already describe almost all motion; optical flow adds GPU time\nand memory for what they miss (some particles and effects)."] = "Los vectores de movimiento del juego ya describen casi todo; el flujo óptico añade tiempo de GPU\ny memoria para lo que se les escapa (algunas partículas y efectos).",
  ["NVIDIA's frame generation model on the game's motion vectors and depth. Highest quality, RTX 40/50."] = "El modelo de generación de cuadros de NVIDIA sobre los vectores de movimiento y la profundidad del juego. Máxima calidad, RTX 40/50.",
  ["Adaptive real-frame pacing"] = "Ritmo adaptativo de cuadros reales",
  ["Up to half headset refresh. Leaves more GPU time for generated frames when adjacent real frames are being missed."] = "Hasta la mitad de la frecuencia del visor. Deja más tiempo de GPU a los cuadros generados cuando se pierden cuadros reales contiguos.",
  ["Uses game motion vectors and depth in both eyes. Adds one intermediate frame between real frames."] = "Usa los vectores de movimiento y la profundidad del juego en ambos ojos. Añade un cuadro intermedio entre cuadros reales.",
  ["HUD"] = "HUD",
  ["Enable HUD panel"] = "Activar panel del HUD",
  ["Head / free-look cone"] = "Cabeza / cono de vista libre",
  ["Follow"] = "Seguimiento",
  ["Catch up beyond the cone, or after 3 seconds at rest when the yaw offset is over 10 degrees inside it."] = "Alcanza fuera del cono, o tras 3 segundos en reposo si el desvío de guiñada supera 10° dentro de él.",
  ["HUD FOV"] = "FOV del HUD",
  ["Stereo depth"] = "Profundidad estéreo",
  ["Off: the HUD has the same direction in both eyes.\nOn: place it at the selected physical depth."] = "Desactivado: el HUD tiene la misma dirección en ambos ojos.\nActivado: lo coloca a la profundidad física elegida.",
  ["Depth"] = "Profundidad",
  ["Brightness"] = "Brillo",
  ["Shadow / outline"] = "Sombra / contorno",
  ["Glow"] = "Resplandor",
  ["INTERACTIONS / DIALOGS"] = "INTERACCIONES / DIÁLOGOS",
  ["World-space interactions / dialogs"] = "Interacciones / diálogos en el mundo",
  ["Interaction free-look cone"] = "Cono de vista libre de interacciones",
  ["Loot free-look cone"] = "Cono de vista libre del botín",
  ["Used while the loot panel and item description are visible. Default: 10 degrees."] = "Se usa mientras se ven el panel de botín y la descripción del objeto. Predeterminado: 10°.",
  ["Interaction distance"] = "Distancia de interacciones",
  ["Interaction FOV"] = "FOV de interacciones",
  ["Interaction prompts and dialog choices share this panel. It follows only beyond the cone; no delayed catch-up at rest."] = "Los avisos de interacción y las opciones de diálogo comparten este panel. Solo sigue fuera del cono; sin alcance diferido en reposo.",
  ["Element"] = "Elemento",
  ["Not currently visible in gameplay; settings are still saved."] = "No visible ahora en el juego; los ajustes se guardan igualmente.",
  ["Show element"] = "Mostrar elemento",
  ["Horizontal offset"] = "Desplazamiento horizontal",
  ["Vertical offset"] = "Desplazamiento vertical",
  ["Size"] = "Tamaño",
  ["Opacity"] = "Opacidad",
  ["Reset element"] = "Restablecer elemento",
  ["Reset all elements"] = "Restablecer todos los elementos",
  ["CONTROLS"] = "CONTROLES",
  ["DRIVING"] = "CONDUCCIÓN",
  ["BINDINGS"] = "ASIGNACIONES",
  ["Movement, weapon aiming and physical interaction shortcuts."] = "Atajos de movimiento, apuntado y de interacción física.",
  ["Hand aim  (off = Decoupled VR Head Aim)"] = "Apuntar con la mano  (desactivado = apuntado VR con la cabeza desacoplado)",
  ["ON (Hand Aim): the controller points the weapon and VRIK drives the arms.\nOFF (Decoupled VR Head Aim): the WEAPON follows your head instead, the game\nkeeps owning its position and its ADS animations, and VRIK stands down for\nthe weapon arm. Either way the shot leaves the real muzzle, for guns and\nprojectiles alike, and free-look while aiming is preserved."] = "ACTIVADO (apuntar con la mano): el control orienta el arma y VRIK mueve los brazos.\nDESACTIVADO (apuntado con la cabeza desacoplado): el ARMA sigue tu cabeza, el juego\nconserva su posición y sus animaciones ADS, y VRIK suelta\nel brazo del arma. En ambos casos el disparo sale de la boca real del cañón, tanto para balas\ncomo para proyectiles, y se conserva la vista libre al apuntar.",
  ["Weapon Aim laser dot (where the bullet hits)"] = "Punto láser del arma (donde impacta la bala)",
  ["Red dot projected from the actual weapon muzzle direction through the\ngame camera -- marks exactly where the bullet will fly."] = "Punto rojo proyectado desde la dirección real de la boca del cañón a través de la\ncámara del juego -- marca exactamente adónde irá la bala.",
  ["Controller vibration"] = "Vibración de los controles",
  ["Haptics: every round by weapon class (handgun, rifle, shotgun, sniper),\nmelee block and parry, bullet block and deflect, reaching a belt element,\npulling a grenade pin. Two-handed grip: both hands; one hand: one."] = "Háptica: cada disparo según la clase de arma (pistola, fusil, escopeta, francotirador),\nbloqueo y parada cuerpo a cuerpo, bloqueo y desvío de balas, alcanzar un elemento del cinturón,\nquitar la anilla de una granada. Agarre a dos manos: ambas manos; a una mano: una.",
  ["Vibration strength"] = "Intensidad de la vibración",
  ["Enable VR -> XInput merge"] = "Activar fusión VR -> XInput",
  ["OR the VR controller state into XInput gamepad 0 every poll.\nOff = the game only sees a physical pad / nothing."] = "Combina (OR) el estado de los controles VR con el control XInput 0 en cada lectura.\nDesactivado = el juego solo ve un control físico / nada.",
  ["Weapon holsters (reach + right grip)"] = "Fundas de armas (alcanzar + gatillo lateral derecho)",
  ["Immersive holsters"] = "Fundas inmersivas",
  ["ON  - equip is chosen by the VISUAL holster you reach for:\n      over the right shoulder = primary weapon (rifle / sniper),\n      hip with a katana = melee, hip with a pistol = sidearm.\nOFF - ignore visual holsters, fixed slot per zone:\n      over-shoulder = EquipmentSlot1, right hip = Slot2, left hip = Slot3.\nReach to the zone and squeeze the RIGHT grip to equip / unequip."] = "ON  - el arma se elige por la funda VISIBLE a la que alcanzas:\n      sobre el hombro derecho = arma principal (fusil / francotirador),\n      cadera con katana = cuerpo a cuerpo, cadera con pistola = arma corta.\nOFF - se ignoran las fundas visibles, ranura fija por zona:\n      sobre el hombro = EquipmentSlot1, cadera derecha = Slot2, cadera izquierda = Slot3.\nAlcanza la zona y aprieta el gatillo lateral DERECHO para equipar / guardar.",
  ["Locomotion direction"] = "Dirección de desplazamiento",
  ["Analog movement"] = "Movimiento analógico",
  ["On: speed follows left-stick travel. Off: the current fixed-speed movement (default).\nVehicle controls keep their existing response."] = "Activado: la velocidad sigue el recorrido del stick izquierdo. Desactivado: el movimiento actual a velocidad fija (predeterminado).\nLos controles de vehículos mantienen su respuesta actual.",
  ["Left stick deadzone"] = "Zona muerta del stick izquierdo",
  ["Right stick deadzone"] = "Zona muerta del stick derecho",
  ["Full input threshold"] = "Umbral de entrada completa",
  ["Raw travel that produces full analog input and activates sprint, dash and crouch.\nThe usable travel between the deadzone and this threshold maps to 0-100%%."] = "Recorrido bruto que da entrada analógica completa y activa esprint, esquiva y agacharse.\nEl recorrido útil entre la zona muerta y este umbral equivale a 0-100%%.",
  ["Game (camera)"] = "Juego (cámara)",
  ["HMD (head)"] = "HMD (cabeza)",
  ["Left hand"] = "Mano izquierda",
  ["Right hand"] = "Mano derecha",
  ["Move source"] = "Origen del movimiento",
  ["Game     - left stick walks the way the camera faces (vanilla).\nHMD      - left stick walks the way the headset faces.\nLeft/Right hand - walks the way the chosen controller points.\nVehicles always keep game heading."] = "Juego    - el stick izquierdo avanza hacia donde mira la cámara (original).\nHMD      - el stick izquierdo avanza hacia donde mira el visor.\nMano izq./der. - avanza hacia donde apunta el control elegido.\nLos vehículos siempre mantienen la dirección del juego.",
  ["Breaststroke swimming"] = "Natación a braza",
  ["Physical crouch"] = "Agacharse físicamente",
  ["Physical crouch depth"] = "Profundidad del agachado físico",
  ["%.0f cm"] = "%.0f cm",
  ["Height loss after the measured lean. Standing back up releases physical crouch."] = "Pérdida de altura tras la inclinación medida. Al erguirse se libera el agachado físico.",
  ["In water: reach forward with both hands, sweep out and pull back.\nMovement begins during the pull. Gentle strokes swim normally; fast pulls boost.\nSwim where the headset points, including up/down; no stick needed.\nTo rise, raise separated hands to chest level and push both down.\nRepeat strokes to keep moving. Pull the left stick back to stop."] = "En el agua: estira ambas manos al frente, ábrelas y tira hacia atrás.\nEl movimiento empieza durante la tracción. Brazadas suaves nadan normal; tracciones rápidas impulsan.\nNadas hacia donde apunta el visor, incluso arriba/abajo; sin stick.\nPara subir, eleva las manos separadas a la altura del pecho y empuja ambas hacia abajo.\nRepite las brazadas para seguir. Tira del stick izquierdo hacia atrás para parar.",
  ["Ladder grip climbing"] = "Trepar escaleras con agarre",
  ["Grip a side rail or rung. Pull the hand down to climb up,\nor move it up to climb down. Release to stop. Native pelvis and legs stay on the ladder."] = "Agarra un larguero o un peldaño. Baja la mano para subir,\no súbela para bajar. Suelta para parar. La pelvis y las piernas nativas siguen en la escalera.",
  ["Auto finish near ladder top"] = "Terminar solo cerca de lo alto de la escalera",
  ["After an upward pull near the top, finish climbing even when grips are released.\nMove the stick or push a held hand upward to cancel."] = "Tras una tracción hacia arriba cerca de lo alto, termina de trepar aunque sueltes los agarres.\nMueve el stick o empuja hacia arriba una mano agarrada para cancelar.",
  ["Ladder finish distance"] = "Distancia para terminar la escalera",
  ["Turning (right stick)"] = "Giro (stick derecho)",
  ["Snap turn"] = "Giro por pasos",
  ["Convert the right-stick X axis into discrete snap pulses\ninstead of smooth rotation. Helps with motion sickness."] = "Convierte el eje X del stick derecho en pasos de giro\nen lugar de rotación suave. Ayuda contra el mareo.",
  ["Snap angle"] = "Ángulo del paso",
  ["STEREO"] = "ESTÉREO",
  ["PERFORMANCE"] = "RENDIMIENTO",
  ["NVIDIA Reflex"] = "NVIDIA Reflex",
  ["Game setting"] = "Ajuste del juego",
  ["Off (higher FPS)"] = "Desactivado (más FPS)",
  ["On (lower latency)"] = "Activado (menos latencia)",
  ["On + Boost"] = "Activado + Boost",
  ["Off can improve GPU utilization and FPS, but may increase input latency."] = "Desactivado puede mejorar el uso de GPU y los FPS, pero puede aumentar la latencia de entrada.",
  ["On"] = "Activado",
  ["Waiting for renderer"] = "Esperando al renderizador",
  ["Applied: %s"] = "Aplicado: %s",
  ["STEREO VIEW"] = "VISTA ESTÉREO",
  ["Mono mode"] = "Modo mono",
  ["One picture for both eyes, drawn once from the centre of the head:\nno depth, the most frames. Engine stereo and the second view are off."] = "Una imagen para ambos ojos, renderizada una vez desde el centro de la cabeza:\nsin profundidad, el máximo de cuadros. El estéreo del motor y la segunda vista están desactivados.",
  ["Restart the game to apply"] = "Reinicia el juego para aplicar",
  ["Motion prediction (ms)"] = "Predicción de movimiento (ms)",
  ["%.1f ms"] = "%.1f ms",
  ["Forward-predicts the head pose by this many ms using head\nvelocity, hiding render-to-photon latency. 0 = off.\nTune up until motion feels responsive without overshoot."] = "Predice la pose de la cabeza esos ms según su\nvelocidad, ocultando la latencia del renderizado a los fotones. 0 = desactivado.\nSúbelo hasta que el movimiento se sienta ágil sin pasarse.",
  ["Stereo separation x"] = "Separación estéreo x",
  ["Personal fine-tune on the auto IPD. 1.0 = calibrated natural\nseparation, auto-scaled to the headset's runtime IPD. Nudge\n0.8-1.2 for taste; crank to 3-5x to exaggerate depth and make\nthe eye alternation obvious on the flat monitor for testing."] = "Ajuste personal del IPD automático. 1.0 = separación natural\ncalibrada, escalada al IPD del runtime del visor. Ajusta\n0.8-1.2 a tu gusto; 3-5x exagera la profundidad y hace\nvisible la alternancia de ojos en el monitor plano para pruebas.",
  ["World scale"] = "Escala del mundo",
  ["Scales eye separation AND head translation together.\nLower it (e.g. 0.8) to make the world look\nBIGGER / yourself smaller; raise to shrink the world. Use this if V\nand NPCs feel too large."] = "Escala a la vez la separación de los ojos Y la traslación de la cabeza.\nBájala (p. ej. 0.8) para que el mundo parezca\nMÁS GRANDE / tú más pequeño; súbela para encoger el mundo. Úsala si V\ny los PNJ parecen demasiado grandes.",
  ["IPD scale"] = "Escala de IPD",
  ["Eye-separation multiplier on the runtime IPD. 1.0 = the neutral\nbaseline (+-0.033 m on a typical headset).\nAffects stereo depth (diorama vs giant), NOT the monocular size."] = "Multiplicador de separación de ojos sobre el IPD del runtime. 1.0 = la base\nneutra (+-0.033 m en un visor típico).\nAfecta a la profundidad estéreo (diorama o gigante), NO al tamaño monocular.",
  ["Reuse last clean frame"] = "Reutilizar el último cuadro limpio",
  ["On stale ticks, re-submit the last clean captured eye and let\nthe compositor reproject it, instead of warping stale content\nagain. May lower submit rate\ntoward the capture rate. Off = always warp the stale eye."] = "En los ticks obsoletos, reenvía el último ojo capturado limpio y deja que\nel compositor lo reproyecte, en lugar de deformar otra vez\nel contenido obsoleto. Puede bajar la frecuencia de envío\nhacia la de captura. Desactivado = deformar siempre el ojo obsoleto.",
  ["Asymmetric projection"] = "Proyección asimétrica",
  ["ON: each eye renders exactly its own off-centre lens window\n(more of the panel used, square pixels).\nOFF: the symmetric frustum sized to the widest half-angle."] = "ON: cada ojo renderiza exactamente su propia ventana de lente descentrada\n(más panel aprovechado, píxeles cuadrados).\nOFF: el frustum simétrico ajustado al semiángulo más ancho.",
  ["AVATAR"] = "AVATAR",
  ["VR shortcuts and default game actions. Button names follow the Touch / Xbox convention; game actions use your controller bindings."] = "Atajos VR y acciones del juego predeterminadas. Los nombres de botones siguen la convención Touch / Xbox; las acciones del juego usan tus asignaciones del control.",
  ["LEFT STICK"] = "STICK IZQUIERDO",
  ["Move. Hold fully forward for 0.2 seconds to sprint."] = "Moverse. Mantén del todo hacia delante 0.2 segundos para esprintar.",
  ["RIGHT STICK  Left / right"] = "STICK DERECHO  Izquierda / derecha",
  ["Turn. Uses your snap-turn setting."] = "Girar. Usa tu ajuste de giro por pasos.",
